(()=>{
 const box=document.querySelector('#original-lightbox'),frame=document.querySelector('.motion-frame iframe'),motionButton=document.querySelector('[data-motion]');let last,ready=false,wantedPlay=location.hash==='#motion';
 function send(action,view){frame.contentWindow?.postMessage({type:'robot-original-motion-command',action,view},location.origin)}
 addEventListener('message',e=>{if(e.source!==frame.contentWindow||e.origin!==location.origin||e.data?.type!=='robot-original-motion-state')return;const state=e.data;ready=state.ready;motionButton.textContent=state.playing?'暂停动效':state.view==='monitor'&&state.ended?'重播巡检':'播放动效';motionButton.setAttribute('aria-pressed',String(!!state.playing));document.querySelectorAll('[data-motion-view]').forEach(b=>b.classList.toggle('active',b.dataset.motionView===state.view));document.querySelector('[data-motion-status]').textContent=state.view==='overview'?(state.hovered>=0?'悬停暂停 / 当前机器人与底座放大':state.playing?'顺时针环绕 / 悬停查看机器人':'已暂停，点击播放环绕'):state.ended?'巡检已完成，可重播':state.playing?'机器人沿轨道巡检':'已暂停，点击播放巡检';if(ready&&wantedPlay){wantedPlay=false;send('play')}});
 frame.addEventListener('load',()=>send('state'));addEventListener('hashchange',()=>{if(location.hash==='#motion'){if(ready)send('play');else wantedPlay=true}});
 document.addEventListener('click',e=>{const image=e.target.closest('[data-image]');if(image){last=image;box.querySelector('img').src=image.dataset.image;box.querySelector('img').alt=image.querySelector('img').alt;box.showModal();return}const zoom=e.target.closest('[data-zoom]');if(zoom){const expanded=document.body.classList.toggle('expanded');zoom.setAttribute('aria-pressed',String(expanded));zoom.setAttribute('aria-label',expanded?'适应窗口':'放大展板')}const choice=e.target.closest('[data-motion-view]');if(choice){send('view',choice.dataset.motionView);return}if(e.target.closest('[data-motion]')){if(ready)send('toggle');else{wantedPlay=true;motionButton.textContent='正在载入动效…'}}});
 box.querySelector('.close').addEventListener('click',()=>box.close());box.addEventListener('click',e=>{if(e.target!==box)return;const r=box.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)box.close()});box.addEventListener('close',()=>last?.focus({preventScroll:true}));
})();
